from pathlib import Path
import gzip,json,sys
import numpy as np
import matplotlib;matplotlib.use('Agg')
import matplotlib.pyplot as plt
import yaml
P=Path(__file__).resolve().parent
x=json.loads(gzip.decompress((P/'results/observations.json.gz').read_bytes()));ext=json.loads(gzip.decompress((P/'results/extension.json.gz').read_bytes()));w=np.array(x['wavelength_nm']);cm=np.loadtxt(P/'data/CIE_xyz_1931_2deg.csv',delimiter=',');il=np.loadtxt(P/'data/CIE_std_illum_D65.csv',delimiter=',')
measured={}
for e in ['Au','Ag','Cu']:
 r=yaml.safe_load((P/'data'/f'{e}_Johnson.yml').read_text());r=np.array([list(map(float,a.split())) for a in r['DATA'][0]['data'].splitlines() if a.strip()]);measured[e]=np.column_stack([np.interp(w,r[:,0]*1000,r[:,j]) for j in [1,2]]).tolist()
data={'parameters':json.loads((P/'data/rakic_parameters.json').read_text()),'wavelength_nm':w.tolist(),'measured_nk':measured,'cmf':np.column_stack([np.interp(w,cm[:,0],cm[:,j]) for j in [1,2,3]]).tolist(),'illuminant':np.interp(w,il[:,0],il[:,1]).tolist(),'ions':x['ions']}
(P/'viewer_data.json').write_text(json.dumps(data,separators=(',',':')))
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Elemental Peel — Compound Eye</title><style>body{background:#08121f;color:#eef2f6;font:17px/1.55 system-ui;margin:0}main{max-width:1100px;margin:auto;padding:35px 22px}h1{font-size:clamp(30px,5vw,54px);margin:8px 0;color:#e8c271}h2{font-size:26px;color:#e8c271}.lead{max-width:900px;color:#c5d4e2}section{padding:20px 0;border-top:1px solid #344456}[hidden]{display:none!important}.controls{display:flex;gap:22px;flex-wrap:wrap;align-items:center;background:#142232;padding:18px;border-radius:10px}label{display:block}input{accent-color:#edc470}button,select{background:#223548;color:#fff;padding:9px;border:1px solid #8796a6;border-radius:6px}canvas{width:100%;height:auto;background:#0c1928;margin-top:14px;border-radius:10px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.metal{background:#142232;padding:16px;border-radius:8px}.swatch{height:75px;margin:10px 0;border-radius:5px}small{font-size:13px;color:#b4c4d5}.note{border-left:3px solid #e8c271;padding-left:14px}a{color:#96d5fa}@media(max-width:650px){.cards{grid-template-columns:repeat(2,1fr)}}#joint{background:#142232;padding:18px}</style><main><small>COMPOUND EYE · ELEMENTAL STUDY · 8 SEPTEMBER 2026</small><h1>Spacing, channels, and the surface</h1><p class="lead">Follow gold, silver, copper, and platinum while a metal film becomes thinner. The optical boundary calculation recomputes immediately, including the reflected color. Then compare the separate atomic ionization sequence and the fixed-gap electronic control.</p><section><h2>1 · Thin the material; watch every optical readout</h2><div class="controls"><label>Thickness <output id="depthValue"></output><br><input id="depth" type="range" min="10" max="200" step="0.1" value="50"></label><label>Substrate index <output id="outsideValue"></output><br><input id="outside" type="range" min="1" max="2" step="0.01" value="1.5"></label><label>Optical input<br><select id="source"><option value="measured">Measured Au/Ag/Cu + fitted Pt</option><option value="fit">Rakić fits for all four</option></select></label><button id="play">Animate thinning</button></div><div id="fitcontrols" class="controls" hidden><label>Interband weight <output id="ibValue"></output><br><input id="ib" type="range" min="0" max="1" step="0.01" value="1"></label><label>Drude damping multiplier <output id="dampingValue"></output><br><input id="damping" type="range" min="0.2" max="5" step="0.1" value="1"></label><small>Changing these fit parameters is a model intervention, not an observed peel.</small></div><p class="note">Smooth, uniform 10–200 nm films; air incidence, normal angle, fixed bulk optical constants, transparent substrate. Below the source thickness range, results are extrapolations. Atomic monolayers, roughness, chemical changes, and percolation need new material inputs. This is a live calculation, not a live laboratory feed.</p><div id="cards" class="cards"></div><canvas id="optics" width="1000" height="330"></canvas><small>R: reflected power · T: transmitted power · A: absorbed power. Color: CIE 1931 2° observer, D65 daylight, 380–780 nm. Metallic appearance also depends on lighting and shape.</small></section><section><h2>2 · The actual atomic removal ladder</h2><canvas id="ions" width="1000" height="330"></canvas><p>NIST ionization energies, first 12 removals. The later shell jump shifts from removal 12 in Cu/Ag/Au to removal 11 in Pt. These are energies for successive isolated ions at fixed nuclear charge. Many high-charge entries are estimates; exact flags and uncertainties are in the package. This graph does not convert ionization thresholds into solid-state band gaps.</p></section><section><h2>3 · Same spacing; different coupling</h2><label>Electronic orientation <output id="angleValue"></output><br><input id="angle" type="range" min="0" max="90" step="0.1" value="45"></label><p id="joint"></p><p>The recovered hypersurface electronic-sheet Hamiltonian now has explicit current contacts. Both optical transition strength and conductance change while the energy gap stays fixed. This is a checked two-level model, separate from the measured elemental spectra above.</p></section><section><h2>Sources and reproduction</h2><p><a href="https://doi.org/10.1103/PhysRevB.6.4370">Johnson & Christy, measured optical constants</a> · <a href="https://doi.org/10.1364/AO.37.005271">Rakić optical fits</a> · <a href="https://physics.nist.gov/asd">NIST atomic spectra</a> · <a href="https://cie.co.at/data-tables">CIE observer and daylight</a></p><p>Open FINDINGS.md and METHODS.md in the complete package for the research synthesis, assumptions, exact identities, source hashes, and execution records. The seven new registered eyes preserve all 191 earlier versions.</p></section></main><script>const DATA=__DATA__;</script><script>__SCRIPT__</script></html>'''
page=page.replace('__DATA__',json.dumps(data,separators=(',',':'))).replace('__SCRIPT__',(P/'viewer.js').read_text());(P/'Elemental_Peel_Observatory.html').write_text(page)
plt.rcParams.update({'figure.facecolor':'#08121f','axes.facecolor':'#101f30','savefig.facecolor':'#08121f','text.color':'#edf1f7','axes.labelcolor':'#c6d4e2','xtick.color':'#c6d4e2','ytick.color':'#c6d4e2','axes.edgecolor':'#627183','font.size':10})
fig,axs=plt.subplots(2,3,figsize=(16,9),layout='constrained');cols={'Au':'#edc363','Ag':'#d6e5f2','Cu':'#e69875','Pt':'#a7aeb8'}
for el,co in cols.items():
 rr=x['ions'][el];axs[0,0].plot(range(1,13),rr['energies_eV'],'o-',color=co,label=el)
 o=x['optics'][el];axs[0,1].plot(w,o.get('Johnson_bulk_R',o['bulk_R']),color=co,label=el+(' (fit)' if el=='Pt' else ''))
 frames=ext['measured_films'].get(el,x['films'][el]);ds=[200,100,50,20,10]
 for j,d in enumerate(ds):
  f=next(a for a in frames if a['d_nm']==d and a['substrate_index']==1.5)
  axs[0,2].add_patch(plt.Rectangle((j,list(cols).index(el)),1,1,color=f['color']['hex']))
axs[0,0].set(xlabel='Electron removal number',ylabel='Ionization energy / eV',title='A · Element-specific shell steps');axs[0,0].legend();axs[0,1].set(xlabel='Wavelength / nm',ylabel='Reflectance',ylim=(0,1.05),title='B · Measured spectra; fitted Pt');axs[0,1].legend()
axs[0,2].set(xlim=(0,5),ylim=(0,4),xticks=np.arange(5)+.5,xticklabels=ds,yticks=np.arange(4)+.5,yticklabels=list(cols),xlabel='Film thickness / nm (substrate n=1.5)',title='C · Reflected daylight during thinning');axs[0,2].invert_yaxis()
r=x['rotation'];th=[a['theta']*180/np.pi for a in r];axs[1,0].plot(th,[a['dipole_strength'] for a in r],color='#edc363',label='Dipole strength');axs[1,0].plot(th,[a['G_over_G0'] for a in r],color='#67cbe1',label='G/G₀');axs[1,0].set(xlabel='Electronic orientation / degrees',ylabel='Declared units',title='D · Fixed 2 eV gap; changing response');axs[1,0].legend()
s=x['side_peel'];axs[1,1].plot([a['coupling_eV'] for a in s],[a['G_over_G0'] for a in s],color='#67cbe1');axs[1,1].set(xlim=(.8,0),xlabel='Remaining side-orbital coupling / eV',ylabel='G/G₀',title='E · Removing interference raises current')
no=x['noise_controls'];width=.35;ii=np.arange(3);axs[1,2].bar(ii-width/2,no[2]['transmissions'],width,color='#edc363',label='Channel set A');axs[1,2].bar(ii+width/2,no[3]['transmissions'],width,color='#67cbe1',label='Channel set B');axs[1,2].set(xticks=ii,xticklabels=['1','2','3'],ylim=(0,1),xlabel='Transmission channel',ylabel='Transmission',title='F · Same G = 1.5 G₀ and F = 0.38');axs[1,2].legend()
fig.suptitle('Elemental peel: put the spacing, coupling, and boundary in the same record',fontsize=20,color='#edc363');fig.savefig(P/'Elemental_Peel_Findings.png',dpi=160);plt.close(fig)
print('Built live HTML and scientific figure')
